<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {Search,Download,ChevronLeft,ChevronRight,ArrowUpRight,Rows3,Table2,X} from 'lucide-vue-next'
import {data,latin,num,colors,saveCSV,type Registry} from './data'
const emit=defineEmits<{open:[Registry]}>()
const query=ref(''),agency=ref(''),type=ref(''),field=ref(''),cohort=ref(''),page=ref(1),matrix=ref(false),matrixBy=ref('field')
const active=computed(()=>!!(query.value||agency.value||type.value||field.value||cohort.value))
const rows=computed(()=>data.registry.filter(x=>(!query.value||latin(x.n+' '+x.b+' '+x.o).toLowerCase().includes(latin(query.value).toLowerCase()))&&(agency.value===''||x.oi===+agency.value)&&(type.value===''||x.ti===+type.value)&&(field.value===''||x.fi===+field.value)&&(cohort.value===''||x.ci===+cohort.value)))
watch([query,agency,type,field,cohort],()=>page.value=1)
const pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/20)))
const dimensions=computed(()=>[{title:'Chora turlari',names:data.types,values:active.value?data.types.map((_,i)=>rows.value.filter(r=>r.ti===i).length):data.typeTotals,selected:type.value,key:'type'},{title:'Yo‘nalishlar',names:data.fields,values:active.value?data.fields.map((_,i)=>rows.value.filter(r=>r.fi===i).length):data.fieldTotals,selected:field.value,key:'field'},{title:'Aholi toifalari',names:data.cohorts,values:active.value?data.cohorts.map((_,i)=>rows.value.filter(r=>r.ci===i).length):data.cohortTotals.map(x=>x.v[0]??0),selected:cohort.value,key:'cohort'}])
const matrixRows=computed(()=>data.agencies.map((a,i)=>({i,name:a.n,total:active.value?rows.value.filter(r=>r.oi===i).length:a.c,values:active.value?(matrixBy.value==='field'?data.fields:data.types).map((_,j)=>rows.value.filter(r=>r.oi===i&&(matrixBy.value==='field'?r.fi:r.ti)===j).length):matrixBy.value==='field'?a.d:a.t})).filter(a=>!active.value||a.total).sort((a,b)=>b.total-a.total))
function select(key:string,i:number){const target=key==='type'?type:key==='field'?field:cohort;target.value=target.value===String(i)?'':String(i)}
function clear(){query.value=agency.value=type.value=field.value=cohort.value=''}
function download(){saveCSV('Choralar_reyestri.csv',[['ID','Chora','Idora','Tur','Yo‘nalish','Toifa','Huquqiy asos'],...rows.value.map(x=>[x.id,latin(x.n),latin(x.o),latin(data.types[x.ti]),latin(data.fields[x.fi]),latin(x.cn),latin(x.b)])])}
</script>
<template><div class="registry-view"><div class="section-heading"><div><h2>Choralar reyestri</h2><p>37 idora · 3 tur · 6 yo‘nalish · 8 aholi toifasi</p></div><button class="np-button" @click="download"><Download :size="14"/>Eksport</button></div><div class="registry-summary"><div><b>{{ num(data.registryTotal) }}</b><span>Manbadagi yig‘ma choralar</span></div><div><b>{{ num(data.registry.length) }}</b><span>Idoralar kesimidagi yozuvlar</span></div><div><b>{{ num(rows.length) }}</b><span>Joriy tanlovdagi yozuvlar</span></div><div><b>{{ new Set(rows.map(x=>x.oi)).size }}</b><span>Tanlovdagi idoralar</span></div></div><div class="registry-dimensions"><section v-for="dimension in dimensions" :key="dimension.key" class="np-card"><h3>{{ dimension.title }}</h3><button v-for="(name,i) in dimension.names" :key="name" class="dimension-row" :class="{selected:dimension.selected===String(i)}" @click="select(dimension.key,i)"><span>{{ latin(name) }}</span><b>{{ dimension.values[i] }}</b><i :style="{width:Math.max(2,(dimension.values[i]??0)/Math.max(...dimension.values,1)*100)+'%',background:colors[i%colors.length]}"/></button></section></div><div class="np-card"><div class="np-toolbar"><label class="np-search"><Search :size="15"/><input v-model="query" placeholder="Chora, idora yoki huquqiy asos bo‘yicha qidirish" aria-label="Reyestr qidiruvi"/></label><select v-model="agency" aria-label="Reyestr idorasi"><option value="">Barcha 37 idora</option><option v-for="(item,i) in data.agencies" :key="i" :value="String(i)">{{ latin(item.n) }}</option></select><button v-if="active" class="np-button" @click="clear"><X :size="14"/>Tozalash</button><div class="np-segment"><button :class="{active:!matrix}" @click="matrix=false"><Rows3 :size="14"/>Ro‘yxat</button><button :class="{active:matrix}" @click="matrix=true"><Table2 :size="14"/>Idoralar matritsasi</button></div></div><template v-if="matrix"><div class="np-toolbar"><p>Idora qatorini bosib unga tegishli choralarni oching.</p><select v-model="matrixBy" aria-label="Matritsa kesimi"><option value="field">Yo‘nalishlar</option><option value="type">Chora turlari</option></select></div><div class="np-table-wrap"><table class="np-table"><thead><tr><th>Mas’ul idora</th><th>Jami</th><th v-for="name in matrixBy==='field'?data.fields:data.types" :key="name">{{ latin(name) }}</th></tr></thead><tbody><tr v-for="row in matrixRows" :key="row.i"><td><button class="text-button" @click="agency=String(row.i);matrix=false">{{ latin(row.name) }} <ArrowUpRight :size="13"/></button></td><td><b>{{ row.total }}</b></td><td v-for="(value,i) in row.values" :key="i"><span class="matrix-cell" :style="{background:`color-mix(in srgb, ${colors[i%colors.length]} ${Math.min(value*2,70)}%, transparent)`}">{{ value||'—' }}</span></td></tr></tbody></table></div></template><template v-else><div class="np-table-wrap"><table class="np-table"><thead><tr><th>Chora nomi</th><th>Mas’ul idora</th><th>Tur / yo‘nalish</th><th>Aholi toifasi</th><th></th></tr></thead><tbody><tr v-for="row in rows.slice((page-1)*20,page*20)" :key="row.id"><td><button class="text-button" @click="emit('open',row)">{{ latin(row.n) }}</button><small>{{ latin(row.b) }}</small></td><td>{{ latin(row.o) }}</td><td><span class="np-tag blue">{{ latin(data.types[row.ti]) }}</span><small>{{ latin(data.fields[row.fi]) }}</small></td><td>{{ latin(row.cn) }}</td><td><button class="icon-button" :aria-label="latin(row.n)+' kartasi'" @click="emit('open',row)"><ArrowUpRight :size="16"/></button></td></tr><tr v-if="!rows.length"><td colspan="5" class="np-empty">Tanlangan mezonlar bo‘yicha chora topilmadi. <button @click="clear">Filtrlarni tozalash</button></td></tr></tbody></table></div><div class="np-pagination"><span>{{ rows.length?((page-1)*20+1):0 }}–{{ Math.min(page*20,rows.length) }} / {{ num(rows.length) }} yozuv</span><button :disabled="page===1" aria-label="Oldingi sahifa" @click="page--"><ChevronLeft :size="16"/></button><b>{{ page }} / {{ pages }}</b><button :disabled="page>=pages" aria-label="Keyingi sahifa" @click="page++"><ChevronRight :size="16"/></button></div></template><details class="np-note"><summary>577 va 613 ko‘rsatkichlari haqida</summary><p>Manbada 577 — yig‘ma jadvaldagi chora soni. Batafsil reyestrda 613 ta idora-chora yozuvi mavjud. Bir chorani bir necha idora ko‘rsatishi mumkin. Filtrlanganda batafsil yozuvlar sanaladi.</p></details></div></div></template>
<style scoped>.registry-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin-bottom:20px}.registry-summary>div{padding:18px 22px;background:var(--card);border:1px solid var(--border);border-radius:11px;display:grid;gap:5px}.registry-summary b{font-size:27px;color:#345cba}.registry-summary span{font-size:11px;color:#8a97a8}.registry-dimensions{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:20px}.dimension-row{position:relative;width:100%;display:flex;justify-content:space-between;gap:9px;text-align:left;font-size:11px;padding:11px 0 9px;border-bottom:2px solid var(--muted);margin:2px 0}.dimension-row span{color:#74849a}.dimension-row b{color:var(--foreground)}.dimension-row i{position:absolute;bottom:-2px;left:0;height:2px;border-radius:6px;transition:width .5s}.dimension-row.selected{background:#edf3ff;padding-left:8px;padding-right:8px}.matrix-cell{display:block;text-align:center;border-radius:4px;padding:5px}.np-table td:first-child{min-width:270px}.np-table td:nth-child(2){min-width:160px}@media(max-width:900px){.registry-dimensions{grid-template-columns:1fr}.registry-summary{grid-template-columns:1fr 1fr}}</style>
